function total(order: any) {
  switch (order.type) {
    case 'sale':
      return order.items.reduce((s: number, i: any) => s + i.price, 0);
    case 'rental':
      return order.items.reduce((s: number, i: any) => s + i.dailyRate * order.days, 0);
    default:
      throw new Error('unknown order type');
  }
}

